{
  "name": "hci_set_tx_buffer",
  "confidence": "medium",
  "docstring": "Updates the queued Bluetooth HCI/Radio transmit buffer pointer, emits event/completion packets for the old or new buffer, and performs brief interrupt-protected TX accounting.",
  "subsystem": "bt",
  "var_renames": {
    "result": "new_buffer",
    "v1": "tx_ctrl",
    "v2": "new_buffer",
    "v3": "old_buffer",
    "v4": "event_buffer",
    "v5": "tx_busy_count",
    "v8": "complete_event_buffer"
  },
  "struct_hints": [
    {
      "offset": 40,
      "meaning": "current/old transmit buffer pointer in the HCI TX context"
    },
    {
      "offset": 44,
      "meaning": "pending/queued transmit buffer pointer in the HCI TX context"
    },
    {
      "offset": 16,
      "meaning": "transmit buffer state byte (2 pending/queued, 4 completed/unchanged)"
    },
    {
      "offset": 24,
      "meaning": "transmit buffer packet/type state byte (3 appears to mark a special completed/terminated state)"
    }
  ]
}
